import type { WizardStep } from '@refy-design/web';
import { WizardStepper } from '@refy-design/web';
import { useState } from 'react';
const steps: WizardStep[] = [
  { id: 'order', label: 'Goal' },
  { id: 'about', label: 'Details' },
  { id: 'types', label: 'Format' },
  { id: 'team', label: 'Team' },
  { id: 'permissions', label: 'Permissions' },
  { id: 'preferences', label: 'Preferences' },
  { id: 'review', label: 'Review' },
];
export function Example() {
  const args = {};
  const [current, setCurrent] = useState('team');
  const index = steps.findIndex((step) => step.id === current);
  return (
    <div style={{ display: 'grid', gap: 16, maxWidth: 980 }}>
      <WizardStepper
        {...args}
        steps={steps}
        current={current}
        variant="horizontal"
        label="Setting up your project"
        onStepChange={setCurrent}
        onBack={() => setCurrent(steps[Math.max(index - 1, 0)].id)}
      />
      <p
        aria-live="polite"
        style={{ margin: 0, color: 'var(--ink-3)', fontSize: 'var(--text-xs)' }}
      >
        Open step: {steps.find((step) => step.id === current)?.label}.
      </p>
    </div>
  );
}

