import type { WizardStep } from '@refy-design/web';
import { WizardStepper } from '@refy-design/web';
import type { ComponentProps } from 'react';
const steps: WizardStep[] = [
  { id: 'order', label: 'Goal' },
  { id: 'about', label: 'Details' },
  { id: 'types', label: 'Format' },
  { id: 'team', label: 'Team' },
  { id: 'permissions', label: 'Permissions' },
  { id: 'preferences', label: 'Preferences' },
  { id: 'review', label: 'Review' },
];
export function Example() {
  const args: Pick<
    ComponentProps<typeof WizardStepper>,
    'steps' | 'current' | 'variant' | 'label' | 'onStepChange'
  > = {
    steps: steps.map((step) =>
      step.id === 'permissions' ? { ...step, disabled: true } : step,
    ),
    current: 'types',
    variant: 'horizontal',
    label: 'Step states',
    onStepChange: () => {},
  };
  return <WizardStepper {...args} />;
}

